"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "orders", "uid": "uid-deployment-orders"},
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
